  ('sin-palabra-prohibida', 'regex', 'Captura textos donde no aparezca la palabra prohibido en ninguna parte.', 5, 'full', '["todo bien","texto normal","permitido"]'::jsonb, '["esto es prohibido","prohibido","x prohibido y"]'::jsonb),
  ('kql-nivel-error', 'kql', 'Deja pasar solo los eventos cuyo campo level sea error.', 1, 'partial', '["{\"level\":\"error\",\"service\":\"auth\"}","{\"level\":\"error\",\"message\":\"algo se cayo\"}","{\"level\":\"ERROR\",\"service\":\"api\"}"]'::jsonb, '["{\"level\":\"warning\",\"service\":\"auth\"}","{\"level\":\"info\",\"message\":\"todo bien\"}","{\"service\":\"auth\",\"message\":\"sin nivel\"}"]'::jsonb),
