  ('kql-status-404', 'kql', 'Deja pasar solo las peticiones con código de estado 404.', 1, 'partial', '["{\"status\":404,\"url\":\"/perdido\"}","{\"status\":404,\"method\":\"GET\"}","{\"status\":404}"]'::jsonb, '["{\"status\":200}","{\"status\":500}","{\"url\":\"/perdido\"}"]'::jsonb),
  ('kql-usuario-admin', 'kql', 'Deja pasar los eventos del usuario admin. El campo está anidado en user.', 1, 'partial', '["{\"user\":{\"name\":\"admin\"},\"service\":\"ssh\"}","{\"user\":{\"name\":\"Admin\"}}","{\"user\":{\"name\":\"admin\",\"id\":1}}"]'::jsonb, '["{\"user\":{\"name\":\"juan\"}}","{\"name\":\"admin\"}","{\"service\":\"ssh\"}"]'::jsonb),
  ('kql-ip-origen', 'kql', 'Deja pasar los eventos que vienen de la dirección 10.0.0.5.', 1, 'partial', '["{\"source\":{\"ip\":\"10.0.0.5\"}}","{\"source\":{\"ip\":\"10.0.0.5\",\"port\":22}}","{\"source\":{\"ip\":\"10.0.0.5\"},\"level\":\"warning\"}"]'::jsonb, '["{\"source\":{\"ip\":\"10.0.0.6\"}}","{\"source\":{\"ip\":\"192.168.1.5\"}}","{\"destination\":{\"ip\":\"10.0.0.5\"}}"]'::jsonb),
  ('kql-metodo-post', 'kql', 'Deja pasar solo las peticiones hechas con el método POST.', 1, 'partial', '["{\"http\":{\"method\":\"POST\"},\"status\":200}","{\"http\":{\"method\":\"post\"}}","{\"http\":{\"method\":\"POST\",\"version\":\"1.1\"}}"]'::jsonb, '["{\"http\":{\"method\":\"GET\"}}","{\"http\":{\"method\":\"PUT\"}}","{\"method\":\"POST\"}"]'::jsonb),
  ('kql-puerto-22', 'kql', 'Deja pasar las conexiones al puerto 22, el de SSH.', 1, 'partial', '["{\"destination\":{\"port\":22}}","{\"destination\":{\"port\":22},\"service\":\"ssh\"}","{\"destination\":{\"port\":22,\"ip\":\"10.0.0.1\"}}"]'::jsonb, '["{\"destination\":{\"port\":80}}","{\"destination\":{\"port\":2222}}","{\"source\":{\"port\":22}}"]'::jsonb),
  ('kql-accion-denegada', 'kql', 'Deja pasar los eventos donde la acción terminó denegada.', 1, 'partial', '["{\"action\":\"denied\",\"service\":\"firewall\"}","{\"action\":\"DENIED\"}","{\"action\":\"denied\",\"source\":{\"ip\":\"1.2.3.4\"}}"]'::jsonb, '["{\"action\":\"allowed\"}","{\"action\":\"accept\"}","{\"service\":\"firewall\"}"]'::jsonb),
