  ('kql-exfiltracion', 'kql', 'Caza posible exfiltración: tráfico de salida de más de diez millones de bytes hacia un dominio que no sea de la empresa.', 5, 'partial', '["{\"network\":{\"direction\":\"outbound\",\"bytes\":50000000},\"destination\":{\"domain\":\"pastebin.com\"}}","{\"network\":{\"direction\":\"outbound\",\"bytes\":11000000},\"destination\":{\"domain\":\"drive.google.com\"}}","{\"network\":{\"direction\":\"outbound\",\"bytes\":90000000},\"destination\":{\"domain\":\"x.io\"}}"]'::jsonb, '["{\"network\":{\"direction\":\"outbound\",\"bytes\":50000000},\"destination\":{\"domain\":\"backup.empresa.com\"}}","{\"network\":{\"direction\":\"inbound\",\"bytes\":50000000},\"destination\":{\"domain\":\"pastebin.com\"}}","{\"network\":{\"direction\":\"outbound\",\"bytes\":1000},\"destination\":{\"domain\":\"pastebin.com\"}}"]'::jsonb),
  ('kql-escritorio-remoto', 'kql', 'Caza inicios de sesión por escritorio remoto (tipo 10) de usuarios de persona, dejando fuera las cuentas de máquina, que terminan en signo de peso.', 5, 'partial', '["{\"event\":{\"action\":\"logon\"},\"winlog\":{\"logon\":{\"type\":10}},\"user\":{\"name\":\"juan\"}}","{\"event\":{\"action\":\"logon\"},\"winlog\":{\"logon\":{\"type\":10}},\"user\":{\"name\":\"admin\"}}","{\"event\":{\"action\":\"logon\"},\"winlog\":{\"logon\":{\"type\":10}},\"user\":{\"name\":\"soporte\"}}"]'::jsonb, '["{\"event\":{\"action\":\"logon\"},\"winlog\":{\"logon\":{\"type\":10}},\"user\":{\"name\":\"PC01$\"}}","{\"event\":{\"action\":\"logon\"},\"winlog\":{\"logon\":{\"type\":2}},\"user\":{\"name\":\"juan\"}}","{\"event\":{\"action\":\"logoff\"},\"winlog\":{\"logon\":{\"type\":10}},\"user\":{\"name\":\"juan\"}}"]'::jsonb),
  ('kql-powershell-codificado', 'kql', 'Caza consolas de Windows (powershell.exe o cmd.exe) arrancadas con argumentos codificados, o sea que lleven -enc.', 5, 'partial', '["{\"process\":{\"name\":\"powershell.exe\",\"args\":\"-enc SQBFAFgA\"}}","{\"process\":{\"name\":\"cmd.exe\",\"args\":\"/c powershell -enc abc\"}}","{\"process\":{\"name\":\"POWERSHELL.EXE\",\"args\":\"-EncodedCommand -enc x\"}}"]'::jsonb, '["{\"process\":{\"name\":\"powershell.exe\",\"args\":\"-File script.ps1\"}}","{\"process\":{\"name\":\"notepad.exe\",\"args\":\"-enc algo\"}}","{\"process\":{\"name\":\"cmd.exe\"}}"]'::jsonb),
