  ('kql-acceso-externo-exitoso', 'kql', 'Caza accesos que funcionaron desde fuera de la red interna. Interno es 10.0 o 192.168, todo lo demás es de fuera.', 5, 'partial', '["{\"event\":{\"outcome\":\"success\"},\"source\":{\"ip\":\"8.8.8.8\"}}","{\"event\":{\"outcome\":\"success\"},\"source\":{\"ip\":\"200.1.2.3\"}}","{\"event\":{\"outcome\":\"SUCCESS\"},\"source\":{\"ip\":\"172.16.0.1\"}}"]'::jsonb, '["{\"event\":{\"outcome\":\"success\"},\"source\":{\"ip\":\"10.0.0.5\"}}","{\"event\":{\"outcome\":\"success\"},\"source\":{\"ip\":\"192.168.1.5\"}}","{\"event\":{\"outcome\":\"failure\"},\"source\":{\"ip\":\"8.8.8.8\"}}"]'::jsonb),
  ('kql-dominio-que-no-resuelve', 'kql', 'Caza consultas DNS a dominios .xyz que además no resolvieron a ninguna dirección. Suele ser señal de un canal encubierto.', 5, 'partial', '["{\"dns\":{\"question\":{\"name\":\"abc123.xyz\"}}}","{\"dns\":{\"question\":{\"name\":\"datos.xyz\"}}}","{\"dns\":{\"question\":{\"name\":\"x.xyz\"},\"resolved\":null}}"]'::jsonb, '["{\"dns\":{\"question\":{\"name\":\"abc123.xyz\"},\"resolved\":\"1.2.3.4\"}}","{\"dns\":{\"question\":{\"name\":\"google.com\"}}}","{\"dns\":{\"question\":{\"name\":\"google.com\"},\"resolved\":\"8.8.8.8\"}}"]'::jsonb),
  ('kql-ejecutable-en-temporales', 'kql', 'Caza archivos ejecutables (exe o dll) escritos en una carpeta temporal. La ruta lleva Temp en el medio.', 5, 'partial', '["{\"file\":{\"path\":\"C:/Users/juan/AppData/Temp/malo.exe\",\"extension\":\"exe\"}}","{\"file\":{\"path\":\"/tmp/Temp/carga.dll\",\"extension\":\"dll\"}}","{\"file\":{\"path\":\"C:/Temp/x.exe\",\"extension\":\"EXE\"}}"]'::jsonb, '["{\"file\":{\"path\":\"C:/Users/juan/AppData/Temp/notas.txt\",\"extension\":\"txt\"}}","{\"file\":{\"path\":\"C:/Windows/System32/bueno.exe\",\"extension\":\"exe\"}}","{\"file\":{\"extension\":\"exe\"}}"]'::jsonb),
  ('kql-api-escritura-fallida', 'kql', 'Caza escrituras a la API que fallaron y que no vengan de un bot. Escritura es POST o PUT, fallo es 400 o más, y el bot se reconoce en el user agent.', 5, 'partial', '["{\"http\":{\"method\":\"POST\"},\"status\":401,\"user_agent\":\"curl/8.0\"}","{\"http\":{\"method\":\"PUT\"},\"status\":500,\"user_agent\":\"Mozilla/5.0\"}","{\"http\":{\"method\":\"POST\"},\"status\":403}"]'::jsonb, '["{\"http\":{\"method\":\"POST\"},\"status\":401,\"user_agent\":\"googlebot/2.1\"}","{\"http\":{\"method\":\"GET\"},\"status\":500,\"user_agent\":\"curl/8.0\"}","{\"http\":{\"method\":\"POST\"},\"status\":200,\"user_agent\":\"curl/8.0\"}"]'::jsonb)
